# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BÜYÜK MİLLET MECLİSİNE KARŞI ÇIKARILAN AYAKLANMALAR (4 GRUP)</text>\n  <rect x="20" y="45" width="320" height="95" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">1. Doğrudan İstanbul Hükûmetinin Çıkardıkları</text>\n  <text x="32" y="88" font-size="11" fill="#7f1d1d">• Ahmet Anzavur Ayaklanması (Balıkesir - Gönen)</text>\n  <text x="32" y="108" font-size="11" fill="#7f1d1d">• Kuvâ-yı İnzibâtiye / Halifelik Ordusu (İzmit - Geyve)</text>\n  <text x="32" y="128" font-size="10" font-weight="bold" fill="#b91c1c">Amaç: Boğazları korumak ve BMM\'yi yok etmek</text>\n  <rect x="360" y="45" width="320" height="95" rx="8" fill="#ffedd5" stroke="#ea580c" stroke-width="2"/>\n  <text x="520" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">2. İstanbul Hükûmeti + İtilaf Kışkırtmaları</text>\n  <text x="372" y="88" font-size="11" fill="#7c2d12">• Bolu, Düzce, Hendek, Adapazarı, Yozgat (Çapanoğlu)</text>\n  <text x="372" y="108" font-size="11" fill="#7c2d12">• Konya (Delibaş Mehmet), Afyon, Milli Aşireti, Cemil Çeto</text>\n  <text x="372" y="128" font-size="10" font-weight="bold" fill="#c2410c">Neden: Dinî duyguların istismarı ve askerlikten kaçış</text>\n  <rect x="20" y="152" width="320" height="95" rx="8" fill="#fef9c3" stroke="#ca8a04" stroke-width="2"/>\n  <text x="180" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">3. Eski Kuvayımilliye Yanlılarının İsyanları</text>\n  <text x="32" y="195" font-size="11" fill="#713f12">• Çerkez Ethem (Kuvâ-yı Seyyare - Kütahya/Gediz)</text>\n  <text x="32" y="215" font-size="11" fill="#713f12">• Demirci Mehmet Efe (Denizli - Isparta çevresi)</text>\n  <text x="32" y="235" font-size="10" font-weight="bold" fill="#a16207">Neden: Düzenli ordu disiplinine girmeyi reddetmeleri</text>\n  <rect x="360" y="152" width="320" height="95" rx="8" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="520" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">4. Azınlıkların Çıkardığı Ayaklanmalar</text>\n  <text x="372" y="195" font-size="11" fill="#312e81">• Pontus Rum Ayaklanması (Orta ve Doğu Karadeniz)</text>\n  <text x="372" y="215" font-size="11" fill="#312e81">• Ermeni İntikam Alayları (Doğu ve Güney Anadolu)</text>\n  <text x="372" y="235" font-size="10" font-weight="bold" fill="#4338ca">Amaç: Anadolu\'da bağımsız devletler kurmak</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BMM\'NİN AYAKLANMALARA KARŞI ALDIĞI ÖNLEMLER VE ETKİLERİ</text>\n  <rect x="20" y="45" width="320" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">BMM\'NİN ALDIĞI TEMEL TEDBİRLER</text>\n  <text x="35" y="92" font-size="11" fill="#14532d">• <tspan font-weight="bold">Yasama:</tspan> Hıyanet-i Vataniye Kanunu (29 Nisan 1920)</text>\n  <text x="35" y="114" font-size="11" fill="#14532d">• <tspan font-weight="bold">Yargı:</tspan> İstiklal Mahkemeleri (Milletvekili hâkimler)</text>\n  <text x="35" y="136" font-size="11" fill="#14532d">• <tspan font-weight="bold">Toplumsal:</tspan> Ankara Müftüsü Rıfat Börekçi Fetvası</text>\n  <text x="35" y="158" font-size="11" fill="#14532d">• <tspan font-weight="bold">Basın:</tspan> Anadolu Ajansı (6 Nisan) &amp; Hâkimiyet-i Milliye</text>\n  <text x="35" y="180" font-size="11" fill="#14532d">• <tspan font-weight="bold">Askerî:</tspan> Seyyar Jandarma ve Düzenli Ordu birlikleri</text>\n  <rect x="35" y="196" width="290" height="26" rx="5" fill="#bbf7d0"/>\n  <text x="180" y="213" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Kanıt: BMM yasama ve yargı gücünü birlikte kullandı.</text>\n  <rect x="360" y="45" width="320" height="190" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#075985">AYAKLANMALARIN SONUÇLARI</text>\n  <text x="375" y="92" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Olumsuz 1:</tspan> Silah, cephane, para ve insan kaybı yaşandı</text>\n  <text x="375" y="114" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Olumsuz 2:</tspan> Yunan ordusunun ilerleyişi kolaylaştı</text>\n  <text x="375" y="136" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Olumsuz 3:</tspan> Kurtuluş Savaşı\'nın zaferi gecikti</text>\n  <text x="375" y="158" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Olumlu 1:</tspan> BMM\'nin Anadolu\'daki otoritesi güçlendi</text>\n  <text x="375" y="180" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Olumlu 2:</tspan> Düzenli ordunun zorunluluğu anlaşıldı</text>\n  <rect x="375" y="196" width="290" height="26" rx="5" fill="#bae6fd"/>\n  <text x="520" y="213" text-anchor="middle" font-size="11" font-weight="bold" fill="#075985">Sonuç: Anadolu\'da tek meşru güç BMM oldu.</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SEVR ANTLAŞMASI\'NIN AĞIR HÜKÜMLERİ VE HUKUKİ GEÇERSİZLİĞİ</text>\n  <rect x="20" y="45" width="320" height="190" rx="10" fill="#ffe4e6" stroke="#e11d48" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9f1239">SEVR\'İN EGEMENLİĞİ YOK EDEN MADDELERİ</text>\n  <text x="35" y="92" font-size="11" fill="#881337">• <tspan font-weight="bold">Toprak:</tspan> Anadolu\'nun parçalanması, İzmir Yunan\'a</text>\n  <text x="35" y="114" font-size="11" fill="#881337">• <tspan font-weight="bold">Boğazlar:</tspan> Türk üyesi olmayan uluslararası komisyon</text>\n  <text x="35" y="136" font-size="11" fill="#881337">• <tspan font-weight="bold">Askerî:</tspan> Zorunlu askerlik yok, 50.700 kişilik kuvvet</text>\n  <text x="35" y="158" font-size="11" fill="#881337">• <tspan font-weight="bold">Maliye:</tspan> İtilaf mali komisyonu ve ağır kapitülasyon</text>\n  <text x="35" y="180" font-size="11" fill="#881337">• <tspan font-weight="bold">Azınlıklar:</tspan> Genişletilmiş ayrıcalıklar ve müdahale</text>\n  <rect x="35" y="196" width="290" height="26" rx="5" fill="#fecdd3"/>\n  <text x="180" y="213" text-anchor="middle" font-size="11" font-weight="bold" fill="#881337">Taslak: San Remo Konferansı (Nisan 1920)</text>\n  <rect x="360" y="45" width="320" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">NEDEN ÖLÜ DOĞMUŞ BİR ANTLAŞMADIR?</text>\n  <text x="375" y="92" font-size="11" fill="#78350f">• <tspan font-weight="bold">Anayasa Kuralı:</tspan> Kanun-ı Esasi\'ye göre antlaşmalar</text>\n  <text x="385" y="110" font-size="11" fill="#78350f">Mebusan Meclisi onayı olmadan yürürlüğe giremez.</text>\n  <text x="375" y="134" font-size="11" fill="#78350f">• <tspan font-weight="bold">Saltanat Şûrası:</tspan> Meclis yerine danışma kurulu onayladı.</text>\n  <text x="375" y="158" font-size="11" fill="#78350f">• <tspan font-weight="bold">BMM\'nin Kararı:</tspan> Antlaşmayı tanımadı ve imzalayanları</text>\n  <text x="385" y="176" font-size="11" fill="#78350f">19 Ağustos 1920\'de vatan haini ilan etti.</text>\n  <rect x="375" y="196" width="290" height="26" rx="5" fill="#fde68a"/>\n  <text x="520" y="213" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">Sonuç: Hukuken geçersiz kağıt parçası kaldı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
